config.query:
query GetProjectVelocity($teamId: String!) {
  team(id: $teamId) {
    issues(filter: { completedAt: { gte: "{{30_days_ago}}" } }) {
      nodes { id completedAt estimate }
    }
    cycles(filter: { startsAt: { gte: "{{90_days_ago}}" } }) {
      nodes { id number completedIssueCount completedEstimate }
    }
  }
}

loop_actions.code:
// Health Score Algorithm (0-100)
const interactions = inputData.interactions || [];
const velocity = inputData.velocity || {};
const tickets = inputData.tickets || {};
const client = inputData.client;

// Factor 1: Engagement frequency (30%)
const avgInteractionsPerWeek = interactions.length / 4.3;
const engagementScore = Math.min(avgInteractionsPerWeek / 3 * 100, 100);

// Factor 2: Project velocity (25%)
const completedIssues = velocity.issues?.nodes?.length || 0;
const expectedVelocity = 15; // issues per month baseline
const velocityScore = Math.min(completedIssues / expectedVelocity * 100, 100);

// Factor 3: Support ticket health (20%)
const criticalTickets = tickets.priority_distribution?.critical || 0;
const avgResolutionHours = tickets.avg_resolution_hours || 0;
const ticketScore = Math.max(100 - (criticalTickets * 10) - (avgResolutionHours > 48 ? 20 : 0), 0);

// Factor 4: Contract timing (15%)
const daysUntilRenewal = Math.ceil((new Date(client.renewal_date) - Date.now()) / (1000 * 60 * 60 * 24));
const renewalScore = daysUntilRenewal > 90 ? 100 : (daysUntilRenewal / 90) * 100;

// Factor 5: Sentiment (10% - placeholder for future sentiment analysis)
const sentimentScore = 80; // Default neutral-positive

// Weighted health score
const healthScore = Math.round(
  (engagementScore * 0.30) +
  (velocityScore * 0.25) +
  (ticketScore * 0.20) +
  (renewalScore * 0.15) +
  (sentimentScore * 0.10)
);

// Risk classification
let riskLevel = 'healthy';
let alertPriority = 'none';
if (healthScore < 40) { riskLevel = 'critical'; alertPriority = 'urgent'; }
else if (healthScore < 60) { riskLevel = 'at_risk'; alertPriority = 'high'; }
else if (healthScore < 75) { riskLevel = 'warning'; alertPriority = 'medium'; }

// Actionable insights
const insights = [];
if (engagementScore < 50) insights.push('Low engagement: No meetings in 2+ weeks');
if (velocityScore < 50) insights.push('Slow project velocity: Deliverables behind schedule');
if (criticalTickets > 3) insights.push(`${criticalTickets} critical support tickets open`);
if (daysUntilRenewal < 60) insights.push(`Contract renewal in ${daysUntilRenewal} days`);
if (avgResolutionHours > 48) insights.push('Support SLA breaches detected');

return {
  client_id: client.id,
  client_name: client.name,
  health_score: healthScore,
  risk_level: riskLevel,
  alert_priority: alertPriority,
  breakdown: {
    engagement: engagementScore,
    velocity: velocityScore,
    tickets: ticketScore,
    renewal: renewalScore,
    sentiment: sentimentScore
  },
  metrics: {
    interactions_last_30d: interactions.length,
    issues_completed_30d: completedIssues,
    open_tickets: tickets.count || 0,
    critical_tickets: criticalTickets,
    avg_resolution_hours: avgResolutionHours,
    days_until_renewal: daysUntilRenewal
  },
  insights: insights,
  recommended_actions: insights.length > 0 ? [
    'Schedule immediate check-in call',
    'Review project timeline and roadblocks',
    'Escalate to executive sponsor'
  ] : ['Continue regular cadence'],
  assessed_at: new Date().toISOString()
};

